python3 -c import sys, time; sys.path.insert(0,'/app')
t0=time.time()
import agent
print('import_time_s', round(time.time()-t0,3))
print('has Agent:', hasattr(agent,'Agent'))
a=agent.Agent()
print('no-arg init ok; horizon =', a.horizon)
# select_action accepts lists and clips out-of-range obs
print(a.select_action([-2.0, 5.0]), a.select_action([0.6, -0.07]), a.select_action([0.5, 0.0]))
# error handling
try:
    agent.Agent().load('/nonexistent_dir_xyz')
except FileNotFoundError as e:
    print('load-missing -> FileNotFoundError OK')
try:
    agent.Agent().load('/app/task-deps')
except (FileNotFoundError, ValueError) as e:
    print('load-no-config -> OK:', type(e).__name__)
try:
    a.select_action([0.0])
except ValueError:
    print('bad-obs -> ValueError OK')
try:
    a.save('/proc/cannot_write_here_xyz/model')
except (OSError, ValueError) as e:
    print('save-bad-path -> OK:', type(e).__name__)

